4347  md_process_inlines(MD_CTX* ctx, const MD_LINE* lines, MD_SIZE n_lines)
  4348  {
  4349      MD_TEXTTYPE text_type;
  4350      const MD_LINE* line = lines;
  4351      MD_MARK* prev_mark = NULL;
  4352      MD_MARK* mark;
  4353      OFF off = lines[0].beg;
  4354      OFF end = lines[n_lines-1].end;
  4355      OFF tmp;
  4356      int enforce_hardbreak = 0;
  4357      int ret = 0;
  4358
  4359      /* Find first resolved mark. Note there is always at least one resolved
  4360       * mark,  the dummy last one after the end of the latest line we actually
  4361       * never really reach. This saves us of a lot of special checks and cases
  4362       * in this function. */
  4363      mark = ctx->marks;
  4364      while(!(mark->flags & MD_MARK_RESOLVED))
  4365          mark++;
  4366
  4367      text_type = MD_TEXT_NORMAL;
  4368
  4369      while(1) {
  4370          /* Process the text up to the next mark or end-of-line. */
  4371          tmp = (line->end < mark->beg ? line->end : mark->beg);
  4372          if(tmp > off) {
  4373              MD_TEXT(text_type, STR(off), tmp - off);
  4374              off = tmp;
  4375          }
  4376
  4377          /* If reached the mark, process it and move to next one. */
  4378          if(off >= mark->beg) {
  4379              switch(mark->ch) {
  4380                  case '\\':      /* Backslash escape. */
  4381                      if(ISNEWLINE(mark->beg+1))
  4382                          enforce_hardbreak = 1;
  4383                      else
  4384                          MD_TEXT(text_type, STR(mark->beg+1), 1);
  4385                      break;
